CREATE TABLE IF NOT EXISTS ai.knowledge_bases(id BIGINT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',embedding_model_id BIGINT NOT NULL REFERENCES ai.model_configs(id),top_k INTEGER NOT NULL DEFAULT 5,similarity_threshold DOUBLE PRECISION NOT NULL DEFAULT 0.5,create_time BIGINT NOT NULL,update_time BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ai.knowledge_documents(id BIGINT PRIMARY KEY,knowledge_id BIGINT NOT NULL REFERENCES ai.knowledge_bases(id) ON DELETE CASCADE,name TEXT NOT NULL,url TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',content_length INTEGER NOT NULL DEFAULT 0,tokens INTEGER NOT NULL DEFAULT 0,segment_max_tokens INTEGER NOT NULL DEFAULT 500,retrieval_count INTEGER NOT NULL DEFAULT 0,status INTEGER NOT NULL DEFAULT 1,create_time BIGINT NOT NULL,update_time BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ai.knowledge_segments(id BIGINT PRIMARY KEY,document_id BIGINT NOT NULL REFERENCES ai.knowledge_documents(id) ON DELETE CASCADE,knowledge_id BIGINT NOT NULL REFERENCES ai.knowledge_bases(id) ON DELETE CASCADE,vector_id TEXT NOT NULL,content TEXT NOT NULL,content_length INTEGER NOT NULL,tokens INTEGER NOT NULL,retrieval_count INTEGER NOT NULL DEFAULT 0,status INTEGER NOT NULL DEFAULT 1,embedding REAL[],create_time BIGINT NOT NULL,update_time BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_ai_knowledge_segment_base ON ai.knowledge_segments(knowledge_id,status);
